			ar: "تم تكرار {clipCount, plural, zero {{clipCountLabel} مقطع} one {مقطع واحد} two {مقطعين} few {{clipCountLabel} مقاطع} many {{clipCountLabel} مقطعًا} other {{clipCountLabel} مقطع}} للأعلى بمقدار {trackCount, plural, zero {{trackCountLabel} مسار} one {مسار واحد} two {مسارين} few {{trackCountLabel} مسارات} many {{trackCountLabel} مسارًا} other {{trackCountLabel} مسار}}.",
