	"Program audio on track 2. With the playhead inside the session, press 1-9 to cut to an angle and Alt+1-9 to switch the microphone until the next switch.":
		{
			ar: "صوت البرنامج على المسار 2. عندما يكون رأس التشغيل داخل الجلسة، اضغط 1-9 للقطع إلى زاوية وAlt+1-9 لتبديل الميكروفون حتى التبديل التالي.",
			de: "Programmton auf Spur 2. Wenn der Abspielkopf in der Sitzung steht, schneiden Sie mit 1–9 auf einen Winkel und wechseln mit Alt+1–9 das Mikrofon bis zur nächsten Umschaltung.",
			es: "Audio de programa en la pista 2. Con el cabezal dentro de la sesión, pulsa 1-9 para cortar a un ángulo y Alt+1-9 para cambiar de micrófono hasta el siguiente cambio.",
			fr: "Audio programme sur la piste 2. Tête de lecture dans la session, appuyez sur 1-9 pour couper vers un angle et sur Alt+1-9 pour changer de micro jusqu'à la commutation suivante.",
			hi: "प्रोग्राम ऑडियो ट्रैक 2 पर है। प्लेहेड सत्र के अंदर हो तो किसी एंगल पर कट के लिए 1-9 और अगले स्विच तक माइक्रोफ़ोन बदलने के लिए Alt+1-9 दबाएँ।",
			it: "Audio di programma sulla traccia 2. Con la testina nella sessione, premi 1-9 per passare a un'angolazione e Alt+1-9 per cambiare microfono fino alla commutazione successiva.",
			ja: "プログラム音声はトラック 2 にあります。再生ヘッドがセッション内にあるとき、1〜9 でアングルにカット、Alt+1〜9 で次の切り替えまでマイクを切り替えます。",
			ko: "프로그램 오디오는 트랙 2에 있습니다. 재생 헤드가 세션 안에 있을 때 1-9를 누르면 앵글로 컷하고, Alt+1-9를 누르면 다음 전환까지 마이크를 바꿉니다.",
			"pt-BR":
				"Áudio do programa na faixa 2. Com o cursor dentro da sessão, pressione 1-9 para cortar para um ângulo e Alt+1-9 para trocar o microfone até a próxima troca.",
			ru: "Программный звук на дорожке 2. Когда указатель внутри сессии, нажмите 1–9, чтобы переключиться на ракурс, и Alt+1–9, чтобы сменить микрофон до следующего переключения.",
			"zh-CN":
				"节目音频位于轨道 2。播放头位于会话内时，按 1-9 切到某个机位，按 Alt+1-9 切换麦克风直到下一次切换。",
		},
