			hi: "चुनी गई क्लिप को उनकी अपनी टाइमलाइन में नेस्ट करें, जो यहाँ एक सीक्वेंस क्लिप के रूप में दिखती है। डीकंपोज़ क्लिप वापस रखता है।",
			it: "Nidifica le clip selezionate in una timeline propria, mostrata qui come un'unica clip di sequenza. Scomponi rimette le clip al loro posto.",
