			ar: "ادرس فيديو مستوردًا قبل صياغة إنتاج جديد. يستخدم ملف التعريف قطعات المشاهد المقيسة ومستويات الصوت والنصوص المرافقة من هذا المشروع.",
			de: "Untersuchen Sie ein importiertes Video, bevor Sie eine neue Produktion entwerfen. Das Profil nutzt gemessene Szenenschnitte, Audiopegel und Untertitel aus diesem Projekt.",
			es: "Estudia un vídeo importado antes de redactar una nueva producción. El perfil usa los cortes de escena medidos, los niveles de audio y los subtítulos de este proyecto.",
			fr: "Étudiez une vidéo importée avant de rédiger une nouvelle production. Le profil utilise les coupes de scène mesurées, les niveaux audio et les sous-titres de ce projet.",
			hi: "नया प्रोडक्शन ड्राफ़्ट करने से पहले किसी इंपोर्ट वीडियो का अध्ययन करें। प्रोफ़ाइल इस प्रोजेक्ट के मापे गए सीन कट, ऑडियो स्तर और कैप्शन उपयोग करती है।",
			it: "Studia un video importato prima di redigere una nuova produzione. Il profilo usa tagli di scena misurati, livelli audio e sottotitoli di questo progetto.",
			ja: "新しい制作を下書きする前に、読み込んだ動画を分析します。プロファイルには、このプロジェクトで測定したシーンカット、音量レベル、字幕が使われます。",
			ko: "새 제작 초안을 작성하기 전에 가져온 영상을 분석하세요. 프로필은 이 프로젝트에서 측정한 장면 컷, 오디오 레벨, 자막을 사용합니다.",
			"pt-BR":
				"Estude um vídeo importado antes de rascunhar uma nova produção. O perfil usa os cortes de cena medidos, os níveis de áudio e as legendas deste projeto.",
			ru: "Разберите импортированное видео, прежде чем готовить новое производство. Профиль использует измеренные склейки сцен, уровни звука и субтитры этого проекта.",
