		es: "Por ejemplo: piano tranquilo que crece hasta una batería cálida",
		fr: "Par exemple : un piano calme qui monte vers des percussions chaleureuses",
		hi: "उदाहरण: शांत पियानो जो गर्म ड्रम्स तक बढ़ता है",
		it: "Per esempio: pianoforte calmo che cresce fino a batterie calde",
		ja: "例: 穏やかなピアノから温かいドラムへ盛り上がる",
		ko: "예: 잔잔한 피아노가 따뜻한 드럼으로 고조되는 음악",
		"pt-BR": "Por exemplo: piano calmo que cresce até uma bateria acolhedora",
		ru: "Например: спокойное фортепиано, переходящее в тёплые барабаны",
		"zh-CN": "例如：舒缓的钢琴逐渐过渡到温暖的鼓点",
