	"Steadies each video clip first (a reusable stabilized copy, as in Media tools), so the framing follows the subject, not the shake.":
		{
			ar: "يثبّت كل مقطع فيديو أولاً (نسخة مستقرة قابلة لإعادة الاستخدام، كما في أدوات الوسائط)، فيتبع التأطير الموضوع لا الاهتزاز.",
			de: "Stabilisiert jeden Videoclip zuerst (eine wiederverwendbare stabilisierte Kopie wie in den Medienwerkzeugen), damit der Ausschnitt dem Motiv folgt, nicht dem Wackeln.",
			es: "Estabiliza primero cada clip de vídeo (una copia estabilizada reutilizable, como en Herramientas de medios), para que el encuadre siga al sujeto y no al temblor.",
			fr: "Stabilise d’abord chaque clip vidéo (une copie stabilisée réutilisable, comme dans les outils média), pour que le cadrage suive le sujet et non les secousses.",
			hi: "पहले हर वीडियो क्लिप को स्थिर करता है (मीडिया टूल्स की तरह दोबारा इस्तेमाल होने वाली स्थिर कॉपी), ताकि फ्रेमिंग विषय का पीछा करे, कंपन का नहीं।",
			it: "Stabilizza prima ogni clip video (una copia stabilizzata riutilizzabile, come negli strumenti media), così l’inquadratura segue il soggetto e non il tremolio.",
			ja: "まず各ビデオクリップを手ぶれ補正します (メディアツールと同じ再利用可能な補正コピー)。フレーミングが揺れではなく被写体を追います。",
			ko: "먼저 각 비디오 클립을 안정화합니다(미디어 도구처럼 재사용 가능한 안정화 사본). 프레이밍이 흔들림이 아닌 피사체를 따라갑니다.",
			"pt-BR":
				"Estabiliza primeiro cada clipe de vídeo (uma cópia estabilizada reutilizável, como nas ferramentas de mídia), para o enquadramento seguir o assunto e não o tremor.",
			ru: "Сначала стабилизирует каждый видеоклип (повторно используемая стабилизированная копия, как в инструментах медиа), чтобы кадр следовал за объектом, а не за тряской.",
			"zh-CN":
				"先稳定每个视频片段（与媒体工具相同的可复用稳定副本），让构图跟随主体而不是抖动。",
		},
